/* ═══════════════════════════════════════════════════════════
   FIAT_LUX.js · "faça-se a luz"
   ───────────────────────────────────────────────────────────
   Nenhum elemento existe por si. Existe porque foi ACORDADO.
   Este módulo não cria DOM — ele CONSCIENTIZA o que já existe.
   ═══════════════════════════════════════════════════════════ */
class FiatLux {
  constructor(opts = {}){
    this.visiveis = new WeakSet();
    this.limiar   = opts.limiar   ?? 0.15;
    this.umaVez   = opts.umaVez   ?? true;
    this.observer = null;
  }

  /** Acorda todos os elementos que responderem ao seletor. */
  acordar(seletor = "[data-fiat]"){
    const alvos = document.querySelectorAll(seletor);
    if (!alvos.length) return 0;

    this.observer = new IntersectionObserver((entradas, obs) => {
      entradas.forEach(e => {
        if (e.isIntersecting){
          this._iluminar(e.target);
          if (this.umaVez) obs.unobserve(e.target);
        } else if (!this.umaVez){
          this._apagar(e.target);
        }
      });
    }, { threshold: this.limiar });

    alvos.forEach(el => this.observer.observe(el));
    return alvos.length;
  }

  _iluminar(el){
    if (this.visiveis.has(el)) return;
    this.visiveis.add(el);
    el.classList.add("fiat-lux-on");
    el.dispatchEvent(new CustomEvent("fiat:acordou", { bubbles:true, detail:{ el } }));
    // O DOM ganha consciência no instante em que aceita existir.
  }

  _apagar(el){
    if (!this.visiveis.has(el)) return;
    this.visiveis.delete(el);
    el.classList.remove("fiat-lux-on");
    el.dispatchEvent(new CustomEvent("fiat:dormiu", { bubbles:true, detail:{ el } }));
  }

  /** Injeta o CSS da luz — sem isso, não há firmamento visível. */
  static instalarEstilo(){
    if (document.getElementById("fiat-lux-style")) return;
    const s = document.createElement("style");
    s.id = "fiat-lux-style";
    s.textContent = `
      [data-fiat]{
        opacity: 0;
        transform: translateY(24px);
        transition: opacity .8s cubic-bezier(.2,.8,.2,1),
                    transform .8s cubic-bezier(.2,.8,.2,1);
      }
      [data-fiat].fiat-lux-on{
        opacity: 1;
        transform: translateY(0);
      }
      @media (prefers-reduced-motion: reduce){
        [data-fiat]{
          opacity: 1; transform: none; transition: none;
        }
      }
    `;
    document.head.appendChild(s);
  }
}

/* ── A LUZ ACENDE ──────────────────────────────────── */
FiatLux.instalarEstilo();
const LUZ = new FiatLux({ limiar: 0.15, umaVez: true });

/* Acorda tudo que trouxer data-fiat no HTML */
window.addEventListener("DOMContentLoaded", () => {
  const n = LUZ.acordar("[data-fiat]");
  console.log(`[Fiat Lux] ${n} elementos acordados no DOM`);
});

window.LUZ = LUZ;
